begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select plan(19);
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configured_at=now(),configuration_reference='local-test0181'where singleton;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-admin-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select ('a1810000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=4 then'SUPPORT_AGENT'else'MATRICIA_ADMIN'end from generate_series(1,4)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b1810000-0000-4000-8000-000000000001','Delivery Test','Delivery Test','ACTIVE','a1810000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c1810000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','a1810000-0000-4000-8000-000000000001','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c1810000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c1810000-0000-4000-8000-000000000001','PROVIDER_OWNER');
insert into public.admin_work_items(id,queue_version_id,organization_id,source_kind,resource_type,resource_id,title_fr,title_ar,priority,due_at,created_by)select 'd1810000-0000-4000-8000-000000000001',id,'b1810000-0000-4000-8000-000000000001','MANUAL_REVIEW','ORGANIZATION','b1810000-0000-4000-8000-000000000001','Dossier de test','ملف اختبار','HIGH',now()+interval'1 hour','a1810000-0000-4000-8000-000000000001'from public.admin_queue_versions where queue_key='EXCEPTIONS'and status='ACTIVE';
insert into public.admin_work_items(id,queue_version_id,organization_id,source_kind,resource_type,resource_id,title_fr,title_ar,priority,due_at,created_by)select 'd1810000-0000-4000-8000-000000000002',id,'b1810000-0000-4000-8000-000000000001','MANUAL_REVIEW','OTHER','outside-scope','Hors périmètre','خارج النطاق','HIGH',now()+interval'1 hour','a1810000-0000-4000-8000-000000000001'from public.admin_queue_versions where queue_key='EXCEPTIONS'and status='ACTIVE';
create temporary table admin_delivery_observed(k text primary key,v jsonb);
grant all on admin_delivery_observed to authenticated,service_role;
select ok(not has_table_privilege('authenticated','private.admin_execution_environment_v1','UPDATE'),'application users cannot alter deployment environment');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.request_admin_operational_action(null,'b1810000-0000-4000-8000-000000000001','CHANGE_CONFIGURATION','PRODUCTION','ORGANIZATION','b1810000-0000-4000-8000-000000000001',repeat('a',64),'{}','Changement dans mauvais environnement','authorization-real-ref',null,null,null,'delivery181-env-mismatch')$$,'42501','ADMIN_DEPLOYMENT_ENVIRONMENT_MISMATCH','target environment cannot be selected by caller');
insert into admin_delivery_observed values('request',public.request_admin_operational_action('d1810000-0000-4000-8000-000000000001','b1810000-0000-4000-8000-000000000001','GRANT_SUPPORT_ACCESS','DEVELOPMENT','ORGANIZATION','b1810000-0000-4000-8000-000000000001',repeat('a',64),'{}','Accès temporaire justifié au dossier',null,'a1810000-0000-4000-8000-000000000004','CASE_SCOPED',now()+interval'30 minutes','delivery181-support'));
select throws_ok($$select public.decide_admin_operational_action((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),'APPROVE','Auto approbation interdite',1,'delivery181-self')$$,'42501','ADMIN_ACTION_DECISION_DENIED','requester cannot self approve');
insert into admin_delivery_observed values('directory',public.list_admin_actor_directory_v1(1,0,'a1810000-0000-4000-8000-000000000001'));
insert into admin_delivery_observed values('roles',public.list_admin_supervision_page_v1(1,0));
select throws_ok($$select public.assert_privacy_production_ready('b1810000-0000-4000-8000-000000000001')$$,'55000','PRIVACY_PRODUCTION_GATE_BLOCKED','empty privacy register blocks production');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select public.decide_admin_operational_action((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),'APPROVE','Contrôles initiaux vérifiés',1,'delivery181-approve1');
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select public.decide_admin_operational_action((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),'APPROVE','Second contrôle indépendant',2,'delivery181-approve2');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.complete_admin_operational_action((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),repeat('b',64),true)$$,'42501','ADMIN_EXECUTOR_RECEIPT_REQUIRED','legacy completion cannot invent a successful effect');
insert into admin_delivery_observed values('execution',public.execute_admin_operational_action_v1((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),extensions.gen_random_uuid()));
insert into admin_delivery_observed values('replay',public.execute_admin_operational_action_v1((select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request'),extensions.gen_random_uuid()));
reset role;
select is((select v->>'outcome'from admin_delivery_observed where k='execution'),'ADMIN_ACTION_EXECUTED','authorized request executes a genuine support grant');
select is((select v->>'result_hash'from admin_delivery_observed where k='replay'),(select v->>'result_hash'from admin_delivery_observed where k='execution'),'execution replay returns the same result hash');
select is((select count(*)from public.admin_support_access_grants where action_request_id=(select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request')),1::bigint,'only one grant exists after retry');
select is((select v->'rows'->0->>'mfa_status'from admin_delivery_observed where k='directory'),'DISABLED','directory reports actual MFA without factors');
select is((select(v->'rows'->0->>'session_count')::integer from admin_delivery_observed where k='directory'),0,'directory reports actual session count');
select ok(private.administration_organization_roles_v1('b1810000-0000-4000-8000-000000000001')@>array['CLIENT','PROVIDER'],'organization classification preserves multiple business roles');
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000004',true);
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.get_my_admin_support_case_v1('d1810000-0000-4000-8000-000000000001')$$,'support reads the exact granted case');
select throws_ok($$select public.get_my_admin_support_case_v1('d1810000-0000-4000-8000-000000000002')$$,'42501','SUPPORT_CASE_GRANT_REQUIRED','support cannot read another resource in the same tenant');
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.get_my_admin_support_case_v1('d1810000-0000-4000-8000-000000000001')$$,'42501','SUPPORT_CASE_DENIED','MFA is checked on every support read');
reset role;
update public.admin_support_access_grants set granted_at=now()-interval'1 hour',expires_at=now()-interval'1 minute'where action_request_id=(select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.get_my_admin_support_case_v1('d1810000-0000-4000-8000-000000000001')$$,'42501','SUPPORT_CASE_GRANT_REQUIRED','expired support grant is refused');
reset role;
update public.admin_support_access_grants set granted_at=now(),expires_at=now()+interval'15 minutes'where action_request_id=(select(v->>'action_request_id')::uuid from admin_delivery_observed where k='request');
set local role authenticated;
select lives_ok($$select public.revoke_admin_support_access_v1((select id from public.admin_support_access_grants where support_user_id=auth.uid()),'Intervention terminée')$$,'support can revoke its own capability');
select throws_ok($$select public.get_my_admin_support_case_v1('d1810000-0000-4000-8000-000000000001')$$,'42501','SUPPORT_CASE_GRANT_REQUIRED','revocation immediately removes access');
reset role;
select ok(exists(select 1 from public.audit_events where action='admin.support.case_read'and resource_id='d1810000-0000-4000-8000-000000000001'),'support access leaves an audit trail');
update private.admin_execution_environment_v1 set environment='PRODUCTION'where singleton;
set local role authenticated;
select set_config('request.jwt.claim.sub','a1810000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1810000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.request_admin_operational_action(null,'b1810000-0000-4000-8000-000000000001','CHANGE_CONFIGURATION','DEVELOPMENT','ORGANIZATION','b1810000-0000-4000-8000-000000000001',repeat('a',64),'{}','Production ne permet pas cible dev',null,null,null,null,'delivery181-prod-spoof')$$,'42501','ADMIN_DEPLOYMENT_ENVIRONMENT_MISMATCH','DEVELOPMENT request on production DB is rejected before effect');
reset role;
select * from finish();
rollback;
